// 讀取 Notion 頁面屬性，檢查觸發條件，組出合約網址
const BASE = 'https://smallwins33.github.io/contract-generator/'; // 模板位置，交接時改成客戶的網址
const TEMPLATES = { 'Charlie': 'contract.html', 'Yoyo': 'contract_yoyo.html' };

const out = [];
for (const item of $input.all()) {
  const page = item.json;
  const p = page.properties;
  if (!p) continue;
  if (!p['產生合約']?.checkbox) continue;
  if (p['合約狀態']?.select?.name === '已產生') continue;

  const t = rt => (rt || []).map(x => x.plain_text).join('');
  const num = x => x?.number ?? 0;
  const date = x => x?.date?.start || '';

  const name = t(p['中文姓名']?.title);
  const days1 = num(p['待產天數']), p1 = num(p['待產每日房費']);
  const days2 = num(p['月子天數']), p2 = num(p['月子每日房費']);
  const dep = num(p['定金']);
  const total = days1 * p1 + days2 * p2;
  const v = (total * 6271 + days1 * 7919 + days2 * 3571 + name.length * 2137 + dep * 97) % 100000;

  const photo = p['證件照']?.files?.[0];
  const imgUrl = photo ? (photo.file?.url || photo.external?.url || '') : '';

  const q = new URLSearchParams({
    n: name,
    en: t(p['護照英文姓名']?.rich_text),
    bd: date(p['西元生日']),
    pp: t(p['護照號碼']?.rich_text),
    addr: t(p['通訊地址']?.rich_text),
    tel: p['電話']?.phone_number || '',
    em: p['Email']?.email || '',
    ga: p['陪客-大']?.number ?? '',
    gc: p['陪客-小']?.number ?? '',
    ecn: t(p['緊急聯絡人']?.rich_text),
    ect: t(p['緊急聯絡人電話']?.rich_text),
    alg: t(p['過敏原']?.rich_text),
    d1: date(p['待產入住日期']),
    days1, r1: p['待產房型']?.select?.name || '', p1,
    edd: date(p['預產期']),
    d2: date(p['月子入住日期']),
    days2, r2: p['月子房型']?.select?.name || '', p2,
    dep, img: imgUrl, v,
  });

  const plan = p['合約方案']?.select?.name || 'Charlie';
  const tmpl = TEMPLATES[plan] || TEMPLATES['Charlie'];

  out.push({ json: {
    pageId: page.id,
    url: BASE + tmpl + '?' + q.toString(),
    filename: `${plan}訂房合約_${name || '未命名'}.pdf`,
  }});
}
return out;
